        .healthy { color: #00ff88; }
        .unhealthy { color: #ff5555; }
    </style>
</head>
<body>
    <div class="header">
        <a href="/hermes/docs/">Docs</a>
        <a href="/hermes/profile/">Profile</a>
        <a href="/hermes/skill/">Skill</a>
        <a href="/hermes/tool/">Tool</a>
        <a href="/hermes/arsify/">Arsify</a>
        <a href="/hermes/dashboard/">Dashboard</a>
        <a href="/hermes/workspace/" target="_blank">Workspace</a>
        <a href="/hermes/kanban/" target="_blank">Kanban</a>
        <a href="/hermes/lobby/">Lobby</a>
        <a href="/hermes/status/">Status</a>
    </div>

    <div class="card">
        <h2>🩺 Hermes Service Status</h2>
        <div id="serviceStatus">Loading...</div>
    </div>

    <script>
        const services = [
            { name: 'Workspace', url: 'http://localhost:3000', port: 3000 },
            { name: 'Kanban', url: 'http://localhost:3001', port: 3001 },
            { name: 'Orchestrator API', url: 'http://localhost:8000/health', port: 8000 },
            { name: 'WebSocket', url: 'http://localhost:8000/ws', port: 8000 },
        ];

        async function checkService(service) {
            try {
                const res = await fetch(service.url, { mode: 'no-cors' });
                return res.ok || res.status === 0; // no-cors returns status 0
            } catch (e) {
                return false;
            }
        }

        async function loadStatus() {
            const container = document.getElementById('serviceStatus');
            container.innerHTML = '';
            for (const svc of services) {
                const isHealthy = await checkService(svc);
                const div = document.createElement('div');
                div.className = 'service';
                div.innerHTML = `
                    <span>${svc.name} (Port ${svc.port})</span>
                    <span class="${isHealthy ? 'healthy' : 'unhealthy'}">
                        ${isHealthy ? '✅ Healthy' : '❌ Unhealthy'}
                    </span>
                `;
                container.appendChild(div);
            }
        }

        loadStatus();
        setInterval(loadStatus, 30000);
    </script>
</body>
</html>

