{"command": "sudo python3 -c "
config_path = '/etc/nginx/sites-enabled/hermes.upshalter.com'
with open(config_path, 'r') as f:
    content = f.read()

old = '''    # Hermes Kanban - Path-based at /hermes/kanban/
    location /hermes/kanban/ {
        rewrite ^/hermes/kanban(/.*)$ \$1 break;
        proxy_pass http://127.0.0.1:3001;
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_cache_bypass \$http_upgrade;
        proxy_read_timeout 86400;
    }'''

new = '''    # Hermes Kanban - Static plugin at /hermes/kanban/
    location /hermes/kanban/ {
        alias /var/www/workstation/hermes/kanban-app/;
        try_files \$uri \$uri/ =404;
        add_header Content-Type \"text/javascript\" if (\$uri ~ \.js\$);
    }'''

content = content.replace(old, new)

with open(config_path, 'w') as f:
    f.write(content)

print('Updated /hermes/kanban/ to serve static files')
""}

